internal sealed class ModToggleService{internal bool IgnoreDependencyWarnings;internal ModToggleService(OverviewRepository r,string s,IReadOnlyList<OverviewMod> knownMods){}internal OverviewToggleResult PrepareTargets(IReadOnlyList<(OverviewMod m,bool enabled)> o,out ModToggleTransaction? t){if(o.Any(v=>v.m.Guid=="bad.mod")){t=null;return new(false,"unsafe target");}t=new ModToggleTransaction(o);return new(true,"");}internal sealed class ModToggleTransaction{readonly IReadOnlyList<(OverviewMod m,bool enabled)> targets;internal ModToggleTransaction(IReadOnlyList<(OverviewMod m,bool enabled)> v){targets=v;}internal OverviewToggleResult Validate()=>new(true,"");internal OverviewToggleResult Apply(){foreach(var v in targets)v.m.TargetEnabled=v.enabled;return new(true,"");}internal OverviewToggleResult Commit()=>new(true,"");internal OverviewToggleResult Rollback()=>new(true,"");}}
