internal sealed class OverviewProfileStore{internal string AppliedId="p",ViewedId="p",RootDirectory="",IndexPath="";internal OverviewProfile Viewed=new();internal OverviewProfile Applied=>Viewed;internal void MarkApplied(string s){AppliedId=s;}internal void RefreshCommittedCache(){Viewed=Read();}internal OverviewProfile Read(){var pair=ProfilePairPersistence.Read(Path.Combine(Viewed.directory,"profile.json"),Path.Combine(Viewed.directory,"config-values.json"));var profile=pair.Profile.ToObject<OverviewProfile>()!;profile.config=pair.Config.ToObject<OverviewConfigSnapshot>()!;return profile;}internal static T DeserializeJson<T>(string s)=>JsonConvert.DeserializeObject<T>(s)!;}
internal sealed partial class OverviewRepository{
internal readonly string Directory;internal string ProfileRuntimeDirectory,RecoveryDraftPath,PackDirectory,ViewedProfileId="p",_savedDraftSignature="";internal OverviewState State=new();internal OverviewConfigSnapshot _draftConfig,_editingRuntimeBaseline;internal List<OverviewProfileMod> _draftMods=new(){new(){guid="test.mod",enabled=true}};internal bool _restoreSavedBaseline;internal int _loadedRevision;internal static int _sharedRevision;internal OverviewConfigService Configs;internal OverviewProfileStore Profiles=new();internal OverviewProfile ViewedProfile=>Profiles.Viewed;internal bool IsProfileDirty=>true;internal OverviewConfigSnapshot Draft=>_draftConfig;internal List<OverviewProfileMod> Mods=>_draftMods;internal bool FailSave;internal string Recovery=>RecoveryDraftPath;
private sealed class RecoverableDraft{public string profileId="";public OverviewState state=new();public OverviewConfigSnapshot config=new(),runtimeBaseline=new();public List<OverviewProfileMod> mods=new();public OverviewProfile savedBaseline=new();public bool restoreSavedBaseline;}
internal OverviewRepository(string root,OverviewConfigService service,OverviewConfigSnapshot config){Directory=Path.Combine(root,"profile");System.IO.Directory.CreateDirectory(Directory);ProfileRuntimeDirectory=Path.Combine(root,"runtime");System.IO.Directory.CreateDirectory(ProfileRuntimeDirectory);PackDirectory=Directory;RecoveryDraftPath=Path.Combine(ProfileRuntimeDirectory,"draft.json");Configs=service;_draftConfig=Clone(config);_editingRuntimeBaseline=Clone(config);_savedDraftProfile=new(){id="p",directory=Directory,config=Clone(config),mods=Clone(_draftMods)};Profiles.RootDirectory=Directory;Profiles.IndexPath=Path.Combine(Directory,"index.json");Profiles.Viewed=Clone(_savedDraftProfile);_appliedSnapshot=Clone(_savedDraftProfile);Save();}
internal OverviewToggleResult ApplyPartialForTest(){_draftMods=new(){new(){guid="test.mod",enabled=false},new(){guid="bad.mod",enabled=false}};return ApplyProfileTransaction(new[]{new OverviewMod(),new OverviewMod{Guid="bad.mod"}},true,ignoreDependencyWarnings:true);}
internal OverviewToggleResult ApplyForTest()=>ApplyProfileTransaction(new[]{new OverviewMod()},true,skipEnablement:true);
internal OverviewProfile ReadSaved()=>Profiles.Read();internal void DiscardForTest(){var p=ReadSaved();_draftConfig=Clone(p.config);_draftMods=Clone(p.mods);}
private static T Clone<T>(T x)=>JsonConvert.DeserializeObject<T>(JsonConvert.SerializeObject(x))!;private bool PlannedEnabled(OverviewMod m)=>_draftMods.First(t=>t.guid==m.Guid).enabled;
