internal int PendingCount=>_pendingConfiguration.restartParameters.Count;
internal static bool FailPending;
private void PersistRecoveryDraft()=>AtomicWrite(RecoveryDraftPath,JsonConvert.SerializeObject(new{config=_draftConfig,mods=_draftMods}));
private void Save(){var p=Clone(ViewedProfile);p.config=Clone(_draftConfig);p.mods=Clone(_draftMods);ProfilePairPersistence.Write(Directory,JObject.FromObject(p),JObject.FromObject(p.config));if(FailSave)throw new IOException("injected after production pair commit");Profiles.Viewed=p;_savedDraftProfile=Clone(p);}
internal static void AtomicWrite(string p,string s){if(FailPending&&p.EndsWith("pending-profile.json"))throw new IOException("pending write fault");System.IO.Directory.CreateDirectory(Path.GetDirectoryName(p)!);ProfilePairPersistence.Atomic(p,s);}
